    /**
     * Method to retrieve the Customer via CustomerFetchOneSummary
     * @param 	summary CustomerFetchOneSummary 
     * @return 	CustomerFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Customer getCustomer( CustomerFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "CustomerFetchOneSummary arg cannot be null" );
    	
    	Customer entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Customer
        	// --------------------------------------
        	CompletableFuture<Customer> futureEntity = queryGateway.query(new FindCustomerQuery( new LoadCustomerFilter( summary.getCustomerId() ) ), ResponseTypes.instanceOf(Customer.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Customer with id " + summary.getCustomerId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


